#!/bin/sh
# Status line for profile ${PROFILE_NAME}.
#
# Composes with the existing graft statusline rather than replacing it: the
# profile name is prepended, and whatever graft prints follows.
# Generated by devkit; edits are lost on `devkit profile sync`.
set -eu
prefix="[${PROFILE_NAME}]"
graft_line="${PROFILE_HARNESS_DIR}/hooks/graft-statusline.cjs"
if [ -x "$graft_line" ] && command -v node >/dev/null 2>&1; then
  rest=$(node "$graft_line" 2>/dev/null || true)
  [ -n "$rest" ] && printf '%s %s\n' "$prefix" "$rest" && exit 0
fi
printf '%s\n' "$prefix"
